update recipes set name = 'Lemon Rice', keywords = array['lemon', 'rice']::text[], search_text = app_normalize_search_text((select concat_ws(' ', recipes.name, array_to_string(recipes.keywords, ' '), coalesce(string_agg(f.search_text, ' '), '')) from recipe_parts rp left join recipe_items ri on ri.part_id = rp.id left join recipe_item_choices ric on ric.part_id = ri.part_id and ric.item_position = ri.position left join foods f on f.id = ric.food_id where rp.recipe_id = recipes.id)) where id = 'bd6e036c-02bf-5efd-8786-58682872097f'::uuid and is_public;
