update recipes set name = 'Sunomono', keywords = array['sunomono', 'pepino', 'cucumber', 'salada']::text[], search_text = app_normalize_search_text((select concat_ws(' ', recipes.name, array_to_string(recipes.keywords, ' '), coalesce(string_agg(f.search_text, ' '), '')) from recipe_parts rp left join recipe_items ri on ri.part_id = rp.id left join recipe_item_choices ric on ric.part_id = ri.part_id and ric.item_position = ri.position left join foods f on f.id = ric.food_id where rp.recipe_id = recipes.id)) where id = 'ee74d21b-6abe-5e11-913c-d84ac53f5dd0'::uuid and is_public;
update recipe_steps set instruction = 'Slice the cucumber very thinly with a mandoline.' where part_id = '4d3cd943-e8d2-4bfa-a879-65e42e4999c7'::uuid and kind = 'regular'::recipe_step_kind and position = 0 and exists (select 1 from recipe_parts rp join recipes r on r.id = rp.recipe_id where rp.id = recipe_steps.part_id and r.is_public);
update recipe_steps set instruction = 'Sprinkle the slices with salt and massage gently. Let them rest for about 10 minutes to release water.' where part_id = '4d3cd943-e8d2-4bfa-a879-65e42e4999c7'::uuid and kind = 'regular'::recipe_step_kind and position = 1 and exists (select 1 from recipe_parts rp join recipes r on r.id = rp.recipe_id where rp.id = recipe_steps.part_id and r.is_public);
update recipe_steps set instruction = 'Squeeze out the excess water with your hands.' where part_id = '4d3cd943-e8d2-4bfa-a879-65e42e4999c7'::uuid and kind = 'regular'::recipe_step_kind and position = 2 and exists (select 1 from recipe_parts rp join recipes r on r.id = rp.recipe_id where rp.id = recipe_steps.part_id and r.is_public);
update recipe_steps set instruction = 'In a bowl, mix the rice vinegar, sugar, and soy sauce. Stir until the sugar fully dissolves.' where part_id = '4d3cd943-e8d2-4bfa-a879-65e42e4999c7'::uuid and kind = 'regular'::recipe_step_kind and position = 3 and exists (select 1 from recipe_parts rp join recipes r on r.id = rp.recipe_id where rp.id = recipe_steps.part_id and r.is_public);
update recipe_steps set instruction = 'Toss the drained cucumber with the dressing.' where part_id = '4d3cd943-e8d2-4bfa-a879-65e42e4999c7'::uuid and kind = 'regular'::recipe_step_kind and position = 4 and exists (select 1 from recipe_parts rp join recipes r on r.id = rp.recipe_id where rp.id = recipe_steps.part_id and r.is_public);
update recipe_steps set instruction = 'Chill for about 10-15 minutes if you prefer it very cold.' where part_id = '4d3cd943-e8d2-4bfa-a879-65e42e4999c7'::uuid and kind = 'regular'::recipe_step_kind and position = 5 and exists (select 1 from recipe_parts rp join recipes r on r.id = rp.recipe_id where rp.id = recipe_steps.part_id and r.is_public);
update recipe_steps set instruction = 'Place the rice in the cooking basket. Rinse under running water until the water runs clear. Set aside.' where part_id = 'bb4998ab-fda3-4f89-bff3-96db5c2dde25'::uuid and kind = 'thermomix'::recipe_step_kind and position = 0 and exists (select 1 from recipe_parts rp join recipes r on r.id = rp.recipe_id where rp.id = recipe_steps.part_id and r.is_public);
update recipe_steps set instruction = 'Pour 600 g of water and the salt into the mixing bowl. Insert the cooking basket with the rice. Steam: [21 min | speed 4].' where part_id = 'bb4998ab-fda3-4f89-bff3-96db5c2dde25'::uuid and kind = 'thermomix'::recipe_step_kind and position = 1 and exists (select 1 from recipe_parts rp join recipes r on r.id = rp.recipe_id where rp.id = recipe_steps.part_id and r.is_public);
update recipe_steps set instruction = 'Carefully remove the cooking basket. Transfer the rice to a bowl.' where part_id = 'bb4998ab-fda3-4f89-bff3-96db5c2dde25'::uuid and kind = 'thermomix'::recipe_step_kind and position = 2 and exists (select 1 from recipe_parts rp join recipes r on r.id = rp.recipe_id where rp.id = recipe_steps.part_id and r.is_public);
update recipe_steps set instruction = 'Fold the olive oil, lemon zest, and lemon juice into the rice.' where part_id = 'bb4998ab-fda3-4f89-bff3-96db5c2dde25'::uuid and kind = 'thermomix'::recipe_step_kind and position = 3 and exists (select 1 from recipe_parts rp join recipes r on r.id = rp.recipe_id where rp.id = recipe_steps.part_id and r.is_public);
update recipe_steps set instruction = 'Season with salt.' where part_id = 'bb4998ab-fda3-4f89-bff3-96db5c2dde25'::uuid and kind = 'thermomix'::recipe_step_kind and position = 4 and exists (select 1 from recipe_parts rp join recipes r on r.id = rp.recipe_id where rp.id = recipe_steps.part_id and r.is_public);
update recipe_steps set instruction = 'Gently fluff with a fork.' where part_id = 'bb4998ab-fda3-4f89-bff3-96db5c2dde25'::uuid and kind = 'thermomix'::recipe_step_kind and position = 5 and exists (select 1 from recipe_parts rp join recipes r on r.id = rp.recipe_id where rp.id = recipe_steps.part_id and r.is_public);
update recipe_steps set instruction = 'Place the onion, garlic, tomato, and olive oil in the mixing bowl.' where part_id = 'e3d91daa-4f6e-497a-9237-204eccd3a87b'::uuid and kind = 'thermomix'::recipe_step_kind and position = 0 and exists (select 1 from recipe_parts rp join recipes r on r.id = rp.recipe_id where rp.id = recipe_steps.part_id and r.is_public);
update recipe_steps set instruction = 'Chop [5 sec | speed 5].' where part_id = 'e3d91daa-4f6e-497a-9237-204eccd3a87b'::uuid and kind = 'thermomix'::recipe_step_kind and position = 1 and exists (select 1 from recipe_parts rp join recipes r on r.id = rp.recipe_id where rp.id = recipe_steps.part_id and r.is_public);
update recipe_steps set instruction = 'Saute [5 min | 120°C | speed 1].' where part_id = 'e3d91daa-4f6e-497a-9237-204eccd3a87b'::uuid and kind = 'thermomix'::recipe_step_kind and position = 2 and exists (select 1 from recipe_parts rp join recipes r on r.id = rp.recipe_id where rp.id = recipe_steps.part_id and r.is_public);
update recipe_steps set instruction = 'Add the rice, salt, and water. Mix well with the spatula.' where part_id = 'e3d91daa-4f6e-497a-9237-204eccd3a87b'::uuid and kind = 'thermomix'::recipe_step_kind and position = 3 and exists (select 1 from recipe_parts rp join recipes r on r.id = rp.recipe_id where rp.id = recipe_steps.part_id and r.is_public);
update recipe_steps set instruction = 'Cook [17 min | 100°C | reverse | speed 1].' where part_id = 'e3d91daa-4f6e-497a-9237-204eccd3a87b'::uuid and kind = 'thermomix'::recipe_step_kind and position = 4 and exists (select 1 from recipe_parts rp join recipes r on r.id = rp.recipe_id where rp.id = recipe_steps.part_id and r.is_public);

commit;
